import { RoomMember } from "@/types/room-member";
import { Room } from "@/types/room";
import { Message } from "@/types/message";
import { Icons } from "@/components/icons";
import { StorageService } from "@/services/storage.service";
import { useState } from "react";
import MembersModal from "./MembersModal";
import MediaModal from "./MediaModal";

interface RoomDetailsProps {
    room: Room | null;
    members: RoomMember[];
    messages: Message[];
    currentUserId: string | null;
    onCloseRoomAction?: () => void; // Destructive action
    onToggleUI?: () => void; // UI Toggle
}

export default function RoomDetails({ room, members, messages, currentUserId, onCloseRoomAction, onToggleUI }: RoomDetailsProps) {
    const [activeModal, setActiveModal] = useState<'members' | 'media' | null>(null);

    if (!room) return null;

    const isCreator = room.creator.$id === currentUserId;

    // Derive media from messages for real-time consistency
    // Filter for messages that have file attributes
    // Use type assertion or check properties if typed loosely, but Message type has them? 
    // Check Message type. It usually has file_id etc if we updated it. 
    // Yes, previous edits added file_id check in ChatArea. Let's assume Message type has them or we check 'image'/'file'.
    // Actually in ChatArea user added file_id to payload. But Message type might not have them explicitly defined in interface?
    // Let's check Message interface file content if needed. But usually it extends Document which is loose or filtered by payload.
    // Wait, recent ChatArea diff showed msg.file_name etc.
    const mediaMessages = messages.filter(m =>
        (m.type === 'IMAGE' || m.type === 'FILE')
    );

    return (
        <>
            <aside className="w-80 bg-surface-base dark:bg-surface-darkElevated border-l border-border-default dark:border-border-darkDefault p-6 overflow-y-auto hidden md:block h-full">
                {/* Added h-full to ensure it takes height */}
                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-semibold text-text-primary dark:text-text-darkPrimary">Room Details</h3>
                    <button onClick={onToggleUI} className="text-text-muted hover:text-text-primary dark:text-text-darkMuted dark:hover:text-text-darkPrimary transition"><Icons.Close className="w-5 h-5" /></button>
                </div>

                {/* Creator or Actions */}
                <section className="mb-8">
                    <p className="text-xs text-text-secondary dark:text-text-darkSecondary mb-2 font-medium">ACTIONS</p>
                    {isCreator ? (
                        <button
                            onClick={onCloseRoomAction}
                            disabled={room.status === 'CLOSED'}
                            className={`w-full border py-3 rounded-xl transition flex items-center justify-center gap-2 ${room.status === 'CLOSED' ? 'border-border-default dark:border-border-darkDefault text-text-muted dark:text-text-darkMuted cursor-not-allowed' : 'border-status-danger/30 text-status-danger dark:text-status-dangerDark hover:bg-status-danger/10'}`}
                        >
                            {room.status === 'CLOSED' ? 'Room Closed' : <><Icons.Lock className="w-4 h-4" /> Close Room</>}
                        </button>
                    ) : (
                        <button className="w-full border border-border-default dark:border-border-darkDefault text-text-secondary dark:text-text-darkSecondary py-3 rounded-xl hover:bg-surface-subtle dark:hover:bg-surface-darkSubtle transition">
                            Exit Room
                        </button>
                    )}
                </section>

                {/* Members */}
                <section className="mb-8">
                    <div className="flex justify-between mb-4">
                        <p className="text-xs text-text-secondary dark:text-text-darkSecondary font-medium">MEMBERS ({members.length})</p>
                        <button onClick={() => setActiveModal('members')} className="text-xs text-brand-primary dark:text-brand-primaryDark cursor-pointer hover:underline">View All</button>
                    </div>
                    {members.slice(0, 5).map(member => (
                        <Member
                            key={member.$id}
                            name={member.user.$id === currentUserId ? "You" : (member.user.username || `User ${member.user.$id.substring(0, 4)}`)}
                            online={member.isActive}
                        />
                    ))}
                </section>

                {/* Media */}
                <section>
                    <div className="flex justify-between mb-3">
                        <p className="text-xs text-text-secondary dark:text-text-darkSecondary font-medium">SHARED MEDIA</p>
                        <button onClick={() => setActiveModal('media')} className="text-xs text-brand-primary dark:text-brand-primaryDark cursor-pointer hover:underline">View All</button>
                    </div>

                    {mediaMessages.length === 0 ? (
                        <div className="h-28 rounded-xl bg-surface-subtle dark:bg-surface-darkSubtle flex items-center justify-center text-xs text-text-muted dark:text-text-darkMuted border border-border-default dark:border-border-darkDefault border-dashed">
                            No Media
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 gap-3">
                            {mediaMessages.slice(0, 6).map(msg => {
                                // Extract file details from message payload or attributes
                                // Assuming message has file_id, file_name stored in it (as per ChatArea upload logic)
                                // We cast to any if types are not updated in interface yet, or use generic record access
                                const m = msg as any;
                                if (!m.file_id) return null;

                                return (
                                    <a
                                        key={msg.$id}
                                        href={StorageService.getFileView(m.file_id).toString()}
                                        target="_blank"
                                        rel="noreferrer"
                                        className="block aspect-square rounded-xl overflow-hidden bg-surface-subtle dark:bg-surface-darkSubtle border border-border-default dark:border-border-darkDefault hover:opacity-90 transition relative group"
                                    >
                                        {msg.type === 'IMAGE' ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img
                                                src={StorageService.getFilePreview(m.file_id, 150, 150).toString()}
                                                alt={m.file_name || 'Image'}
                                                className="w-full h-full object-cover"
                                            />
                                        ) : (
                                            <div className="w-full h-full flex flex-col items-center justify-center p-2 text-center">
                                                <Icons.Paperclip className="w-6 h-6 text-brand-primary dark:text-brand-primaryDark mb-1" />
                                                <span className="text-[10px] text-text-secondary dark:text-text-darkSecondary truncate w-full">{m.file_name || 'File'}</span>
                                            </div>
                                        )}
                                    </a>
                                );
                            })}
                        </div>
                    )}
                </section>
            </aside>

            {/* Modals */}
            {activeModal === 'members' && (
                <MembersModal
                    isOpen={true}
                    onClose={() => setActiveModal(null)}
                    members={members}
                    currentUserId={currentUserId}
                />
            )}
            {activeModal === 'media' && (
                <MediaModal
                    isOpen={true}
                    onClose={() => setActiveModal(null)}
                    mediaMessages={mediaMessages}
                />
            )}
        </>
    );
}

function Member({ name, online }: { name: string; online?: boolean }) {
    return (
        <div className="flex items-center gap-3 mb-3">
            <div className="w-9 h-9 rounded-full bg-brand-muted dark:bg-brand-mutedDark flex items-center justify-center text-xs text-brand-primary dark:text-brand-primaryDark font-bold">
                {name.charAt(0)}
            </div>
            <div>
                <p className="text-sm font-medium text-text-primary dark:text-text-darkPrimary">{name}</p>
                <p className={`text-xs ${online ? "text-status-success dark:text-status-successDark" : "text-text-muted dark:text-text-darkMuted"}`}>
                    {online ? "active" : "inactive"}
                </p>
            </div>
        </div>
    );
}
